import React from 'react';
import ImageWithFallback from './ImageWithFallback';

const CaseCard = ({ case: caseData, onOpen, balance = Infinity }) => {
  return (
    <div className="card h-100 hover-lift shine">
      <div className="card-body text-center p-4">
        <div className="case-image-container mb-4">
          <ImageWithFallback
            src={caseData.image_url}
            alt={caseData.name}
            className="case-image img-fluid"
            style={{ maxWidth: '120px', maxHeight: '120px' }}
          />
        </div>
        <h5 className="card-title h5 mb-3">{caseData.name}</h5>
        <p className="card-text text-muted mb-4">{caseData.description || 'A mysterious case with valuable rewards'}</p>
        <div className="mb-4">
          <span className={`badge bg-${caseData.color.toLowerCase()} fs-5 px-4 py-2`}>
            {caseData.price.toLocaleString()} €
          </span>
        </div>
        <button className="btn btn-primary w-100 pw-btn" disabled={Number(balance) < Number(caseData.price)} onClick={() => onOpen(caseData.id)}>
          {Number(balance) >= Number(caseData.price) ? 'OPEN CASE' : 'INSUFFICIENT BALANCE'}
        </button>
      </div>
    </div>
  );
};

export default CaseCard;
